body > div > div > a{
      margin-left: auto;
}
#Titulo{
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;
    width: min(100%, 1100px);
    margin: 0 auto;
}
#Titulo > div {
    margin-left: auto;
}
#Logo {
    display: block;
    flex: 0 0 auto;
    width: clamp(56px, 8vw, 100px);
    height: auto;
}

#Hotel {
    margin: 0;
    font-family: "MonsterF";
    font-size: clamp(24px, 5vw, 40px);
    line-height: 1.1;
    overflow-wrap: anywhere;
}

/* O rótulo parece um botão; a caixa marcada representa o estado ligado. */
.estado-toggle {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

#estado-toggle-label {
    display: inline-flex;
    min-height: 44px;
    align-items: center;
    justify-content: center;
    padding: 22px 22px;
    color: #ffffff;
    background: #250000;
    border: 2px solid #bbab20;
    border-radius: 8px;
    font-family: "DeterminationMono";
    cursor: pointer;
}

#estado-toggle:checked + #estado-toggle-label {
    background: #691212;
}

#estado-toggle:focus-visible + #estado-toggle-label {
    outline: 2px solid #bbab20;
    outline-offset: 3px;
}

#Return {
    display: inline-flex;
    min-height: 44px;
    align-items: center;
    justify-content: center;
    padding: 8px 12px;
    font-family: "DeterminationMono";
    font-size: clamp(18px, 3vw, 23px);
    color: #ffffff;
    -webkit-text-fill-color: #ffffff;
}

#Return:focus-visible {
    outline: 2px solid #bbab20;
    outline-offset: 3px;
}

@media (max-width: 480px) {
    body {
        padding: 12px;
    }

    #Titulo {
        gap: 8px;
    }

    #Titulo > div {
        margin-left: auto;
    }
}

@media (max-width: 600px) {
    *,
    *::before,
    *::after {
        box-sizing: border-box;
    }

    html,
    body {
        min-width: 0;
    }

    body {
        padding: 12px;
    }

    #Titulo {
        flex-wrap: wrap;
        gap: 8px;
        min-width: 0;
    }

    #Logo {
        width: 15.5%;
        flex: 0 0 auto;
    }

    #Hotel {
        min-width: 0;
        font-size: 155%;
    }

    #Titulo > div {
        margin-left: auto;
    }

    #Titulo > div > a {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
    }

    #Return {
        float: none;
        margin: 0;
        transform: translateY(-30px);
        padding: 8px 10px;
        font-size: 18px;
        white-space: nowrap;
    }

    #estado-toggle-label {
    display: inline-flex;
    min-height: 22px;
    align-items: center;
    justify-content: center;
    padding: 11px 11px;
    transform: translateX(5px);
    }
}

.Ficha {
    width: min(100%, 1100px);
    margin: 24px auto 0;
    padding: clamp(16px, 3vw, 28px);
    color: #ffffff;
    a{
